    enum ScenarioState { APPROACHING, LANE_SPLITTING, PASSED_SUT, COMPLETE };
    ScenarioState current_state;

public:
    void initialize_scenario() {
        // Initialize vehicle parameters
        position = Vector3D(0, 0, 0);
        velocity = Vector3D(0, 0, 0);
        speed = 0;
        current_lane = 0;
        target_lane = 1;
        current_state = APPROACHING;

        // Set timing sequence
        approach_start_time = 0.0f;
        lane_split_start_time = 2.0f;  // Start lane splitting at 2 seconds
        pass_sut_time = 5.0f;          // Pass SUT at 5 seconds
    }

    void update_frame(float timestamp) {
        switch(current_state) {
            case APPROACHING:
                handle_approach(timestamp);
                break;
            case LANE_SPLITTING:
                handle_lane_splitting(timestamp);
                break;
            case PASSED_SUT:
                handle_passed_sut(timestamp);
                break;
            case COMPLETE:
                return;
        }

        // Update vehicle position
        update_position();

        // Process sensor data
        process_sensor_data();

        // Check state transitions
        check_transitions(timestamp);
    }

private:
    void handle_approach(float timestamp) {
        // Approach SUT with constant speed
        if (timestamp >= approach_start_time) {
            speed = 25.0f;  // 25 m/s approach speed
            velocity.x = speed;
        }
    }

    void handle_lane_splitting(float timestamp) {
        // Execute lane splitting maneuver
        if (timestamp >= lane_split_start_time) {
            // Path planning: move to target lane
            current_lane = target_lane;

            // Speed adjustment for lane splitting
            speed = 30.0f;  // Increased speed during lane splitting

            // Collision avoidance calculation
            if (detect_collision()) {
                speed = std::max(0.0f, speed - 5.0f);  // Reduce speed to avoid collision
            }
        }
    }

    void handle_passed_sut(float timestamp) {
        // Continue moving after passing SUT
        if (timestamp >= pass_sut_time) {
            speed = 20.0f;  // Normal speed after passing
        }
    }

    void update_position() {
        // Frame-by-frame position update
        position.x += velocity.x * FRAME_TIME;
        position.y += velocity.y * FRAME_TIME;
        position.z += velocity.z * FRAME_TIME;
    }

    void process_sensor_data() {
        // Handle sensor data processing
        sensor_readings.clear();
        // Simulate sensor readings
        sensor_readings.push_back(SensorData{position.x, position.y, position.z});
    }

    bool detect_collision() {
        // Simple collision detection algorithm
        // Check proximity to other vehicles in adjacent lanes
        return false;  // Placeholder implementation
    }

    void check_transitions(float timestamp) {
        // State transition management
        if (timestamp >= lane_split_start_time && current_state == APPROACHING) {
            current_state = LANE_SPLITTING;
        } else if (timestamp >= pass_sut_time && current_state == LANE_SPLITTING) {
            current_state = PASSED_SUT;
        } else if (timestamp >= pass_sut_time + 2.0f && current_state == PASSED_SUT) {
